<script setup lang="ts">
defineProps<{fields:{code:string;label:string;type:string;options?:{label:string;value:string|number|boolean}[]}[];modelValue:Record<string,unknown>;remoteOptions?:Record<string,{label:string;value:string|number|boolean}[]>}>();
const emit = defineEmits<{(e:'search'):void;(e:'update:modelValue',v:Record<string,unknown>):void}>();
</script>
<template><el-form class="crud-query" inline @submit.prevent="emit('search')"><el-form-item v-for="f in fields" :key="f.code" :label="f.label"><slot :name="`query-${f.code}`" :field="f"><el-input v-if="f.type==='text'" :model-value="modelValue[f.code]" clearable @update:model-value="(v:any)=>emit('update:modelValue',{...modelValue,[f.code]:v})"/><el-select v-else-if="f.type==='select'" :model-value="modelValue[f.code]" clearable @update:model-value="(v:any)=>emit('update:modelValue',{...modelValue,[f.code]:v})"><el-option v-for="o in remoteOptions?.[f.code]||f.options||[]" :key="String(o.value)" :label="o.label" :value="o.value"/></el-select></slot></el-form-item><el-button type="primary" @click="emit('search')">查询</el-button><el-button @click="emit('update:modelValue',{})">重置</el-button></el-form></template>
